// Cache the public app interface only. All classroom records, AI reviews,
// books, slides and recordings use their existing authenticated online APIs.
const CACHE='richmount-interface-20261030-save1';
const FILES=['/index.html','/install.html','/install.js','/install.css','/assets/student-app-qr.svg','/assets/teacher-app-qr.svg','/app.js','/classroom.js','/classroom-config.js','/navigation.js','/data.js','/grammar.js','/course.js','/lessons.js','/materials.js','/materials-data.js','/audio.js','/vocabulary.js','/vocabulary-data.js','/coaching.js','/writing-studio.js','/answer-autosave.js','/automatic-feedback.js','/writing-studio.css','/notifications.js','/weekly.js','/floating-audio.js','/daily-learning.js','/attendance.js','/slides.js','/book-reader.js','/book-grades.js','/mobile.js','/style.css','/classroom.css','/course.css','/lessons.css','/materials.css','/audio.css','/vocabulary.css','/coaching.css','/notifications.css','/weekly.css','/floating-audio.css','/daily-learning.css','/attendance.css','/mobile.css','/assets/richmount-logo.jpg','/assets/app-icon-192.png','/assets/app-icon-512.png','/assets/apple-touch-icon.png'];
const PUBLIC=new Set(FILES);
function interfaceRequest(request){const url=new URL(request.url);return request.method==='GET'&&url.origin===self.location.origin&&!request.headers.has('Authorization')&&!request.headers.has('Range')&&[...url.searchParams.keys()].every(k=>k==='v')&&(PUBLIC.has(url.pathname)||request.mode==='navigate'&&url.pathname==='/');}
function cacheable(response,path){if(!response.ok||response.redirected||response.type!=='basic'||/private|no-store/i.test(response.headers.get('Cache-Control')||''))return false;const mime=response.headers.get('Content-Type')||'';return path==='/'||path==='/index.html'||path==='/install.html'?/^text\/html/i.test(mime):/\.js$/.test(path)?/javascript/i.test(mime):/\.css$/.test(path)?/^text\/css/i.test(mime):/\.png$/.test(path)?/^image\/png/i.test(mime):/\.jpg$/.test(path)?/^image\/jpeg/i.test(mime):/\.svg$/.test(path)?/^image\/svg\+xml/i.test(mime):false;}
self.addEventListener('install',event=>{event.waitUntil((async()=>{const cache=await caches.open(CACHE);for(const path of FILES){const response=await fetch(new Request(path,{cache:'reload',credentials:'omit'}));if(!cacheable(response,path))throw new Error('App interface file is unavailable: '+path);await cache.put(path,response);}})());});
self.addEventListener('activate',event=>{event.waitUntil((async()=>{for(const key of await caches.keys())if(key.startsWith('richmount-interface-')&&key!==CACHE)await caches.delete(key);await self.clients.claim();})());});
self.addEventListener('fetch',event=>{if(!interfaceRequest(event.request))return;event.respondWith((async()=>{const url=new URL(event.request.url),key=url.pathname==='/'?'/index.html':url.pathname;try{const response=await fetch(event.request);if(cacheable(response,url.pathname)){const cache=await caches.open(CACHE);await cache.put(key,response.clone());}return response;}catch{const cached=await caches.match(key,{cacheName:CACHE});if(cached)return cached;throw new Error('Connect to the internet to open this page.');}})());});
